{"command": "python -c "
import fitz, sys, re
sys.stdout.reconfigure(encoding='utf-8')
doc = fitz.open('esp-dev-kits-zh_CN-master-esp32p4.pdf')
print('=== 摄像头型号候选 ===')
for i in range(doc.page_count):
    t = doc[i].get_text()
    for m in re.finditer(r'(GC\d+|OV\d+|SC\d+|BF\d+|IMX\d+|HM\d+)[A-Z0-9]*', t):
        print(f'[p{i+1}] {m.group(0)}')
print('=== ESP-Hosted / C6连接 ===')
for i in range(doc.page_count):
    t = doc[i].get_text()
    if 'ESP-Hosted' in t or 'Hosted' in t:
        idx = t.find('Hosted'); print(f'[p{i+1}]', t[max(0,idx-100):idx+150].replace(chr(10),' '))
" 2>&1 | Select-Object -First 30", "description": "Search PDF for camera sensor model and ESP-Hosted", "workdir": "E:\Desktop\Openvela"}

