  s_stub_frame.width  = STUB_W;
  s_stub_frame.height = STUB_H;
  s_stub_frame.pixels = s_stub_pixels;

  std::printf("camera: 桩模式（TODO Phase 3: MIPI-CSI 真采集）\n");
