    ["你好","谢谢","爱","好","行","吃","水","来","走","家"]
  ];

  let mode = 0;
  const resultLabel = document.getElementById('resultLabel');
  const confFill = document.getElementById('confFill');
  const statusText = document.getElementById('statusText');
  const thVal = document.getElementById('thVal');
  const thSlider = document.getElementById('thSlider');

  document.querySelectorAll('.mode-btn').forEach(b => {
    b.addEventListener('click', () => {
      document.querySelectorAll('.mode-btn').forEach(x => x.classList.remove('active'));
      b.classList.add('active');
      mode = +b.dataset.mode;
      resultLabel.textContent = '等待识别...';
      confFill.style.width = '0%';
      statusText.textContent = '模式：' + ['数字','字母','词'][mode];
    });
  });

  thSlider.addEventListener('input', () => {
    thVal.textContent = thSlider.value + '%';
  });

  document.getElementById('simBtn').addEventListener('click', () => {
    const list = labelsMode[mode];
    const idx = Math.floor(Math.random() * list.length);
    const conf = 72 + Math.floor(Math.random() * 26); // 72-97
    resultLabel.textContent = list[idx] + '  (' + conf + '%)';
    confFill.style.width = conf + '%';
    statusText.textContent = '识别成功：' + list[idx] + '（模拟语音播报）';
  });
</script>
</body>
</html>
