content.text:
name: cla-check

on:
  pull_request_target:
    types: [opened, reopened, synchronize]
  issue_comment:
    types: [created]
  workflow_call:

permissions:
  contents: read
  pull-requests: write
  statuses: write
  checks: write

concurrency:
  group: cla-check-${{ github.event.pull_request.number || github.ref }}
  cancel-in-progress: true

jobs:
  cla-check:
    if: github.event_name == 'pull_request_target' || github.event_name == 'pull_request' || github.event_name == 'workflow_call' || (github.event.issue.pull_request && contains(github.event.comment.body, '/check-cla'))
    runs-on: ubuntu-latest
    steps:
      - name: Get PR Info
        id: pr-info
        uses: actions/github-script@v7
        with:
          script: |
            let pr;
            let triggerType = 'pr'; // 'pr' or 'comment'

            if (context.eventName === 'issue_comment') {
              // Direct issue_comment event (not via workflow_call)
              triggerType = 'comment';
              const { data } = await github.rest.pulls.get({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: context.issue.number
              });
              pr = data;
            } else if (context.eventName === 'workflow_call') {
              // Called as reusable workflow from docs.yml
              // Check if the original trigger was an issue_comment (/check-cla)
              if (context.payload.comment && context.payload.issue) {
                triggerType = 'comment';
                const { data } = await github.rest.pulls.get({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  pull_number: context.payload.issue.number
                });
                pr = data;
              } else if (context.payload.pull_request) {
                pr = context.payload.pull_request;
              } else {
                core.setOutput('author', 'unknown');
                core.setOutput('head_sha', context.sha);
                core.setOutput('commits_url', '');
                core.setOutput('pr_number', '0');
                core.setOutput('trigger_type', 'pr');
                return;
              }
            } else {
              // pull_request or pull_request_target event
              pr = context.payload.pull_request;
            }

            core.setOutput('author', pr.user.login);
            core.setOutput('head_sha', pr.head.sha);
            core.setOutput('commits_url', pr.commits_url);
            core.setOutput('pr_number', pr.number.toString());
            core.setOutput('trigger_type', triggerType);

      - name: Check CLA for All Commits
        id: cla
        continue-on-error: true
        timeout-minutes: 5
        run: |
          set +e
          COMMITS_URL="${{ steps.pr-info.outputs.commits_url }}"

          ALL_EMAILS=$(curl -s -H "Authorization: token ${{ secrets.GITHUB_TOKEN }}" \
            "$COMMITS_URL" | jq -r '.[].commit.author.email' | sort | uniq)
          CURL_EXIT=$?

          if [ $CURL_EXIT -ne 0 ] || [ -z "$ALL_EMAILS" ]; then
            echo "⚠️ Failed to fetch commit emails (exit code: $CURL_EXIT)"
            echo "error=api_error" >> $GITHUB_OUTPUT
            echo "signed=false" >> $GITHUB_OUTPUT
            exit 0
          fi

          VALID_EMAILS=$(echo "$ALL_EMAILS" | grep -v "noreply.github.com" | grep -v "^$" | grep -v "null")

          if [ -z "$VALID_EMAILS" ]; then
            # No verifiable emails found. Distinguish two cases so we can give a
            # friendlier hint instead of a generic error:
            #   1) All commit emails are GitHub noreply addresses -> noreply_only
            #   2) Genuinely no usable email could be determined   -> no_email
            NOREPLY_EMAILS=$(echo "$ALL_EMAILS" | grep "noreply.github.com")
            if [ -n "$NOREPLY_EMAILS" ]; then
              echo "⚠️ All commit emails are GitHub noreply addresses; cannot verify CLA:"
              echo "$NOREPLY_EMAILS" | sed 's/^/  - /'
              NOREPLY_LIST=$(echo "$NOREPLY_EMAILS" | paste -sd ',' -)
              echo "noreply_emails=$NOREPLY_LIST" >> $GITHUB_OUTPUT
              echo "error=noreply_only" >> $GITHUB_OUTPUT
            else
              echo "❌ Could not determine any email from commits"
              echo "error=no_email" >> $GITHUB_OUTPUT
            fi
            echo "signed=false" >> $GITHUB_OUTPUT
            exit 0
          fi

          echo "📧 Checking CLA for contributors:"
          echo "$VALID_EMAILS" | sed 's/^/  - /'

          UNSIGNED_EMAILS=""
          SIGNED_EMAILS=""
          ALL_SIGNED=true
          CHECKED_EMAILS=""

          while IFS= read -r EMAIL; do
            if [ ! -z "$EMAIL" ]; then
              echo "   🔍 Checking $EMAIL..."

              # 添加超时和重试机制
              RESPONSE=""
              RETRY_COUNT=0
              MAX_RETRIES=3

              while [ $RETRY_COUNT -lt $MAX_RETRIES ] && [ -z "$RESPONSE" ]; do
                if [ $RETRY_COUNT -gt 0 ]; then
                  echo "   ⏳ Retry $RETRY_COUNT for $EMAIL..."
                  sleep 2
                fi

                # 使用超时设置的 curl 命令
                RESPONSE=$(curl -s --max-time 10 --connect-timeout 5 \
                  "https://vela-website.hybrid.xiaomi.com/openvela_cla/check?email=$EMAIL" 2>/dev/null || echo "")

                RETRY_COUNT=$((RETRY_COUNT + 1))
              done

              if [ -z "$RESPONSE" ]; then
                echo "   ⚠️ $EMAIL - API timeout, assuming NOT signed"
                RESPONSE="TIMEOUT"
              fi

              if [ "$RESPONSE" != "EMAIL_SIGNED" ]; then
                if [ -z "$UNSIGNED_EMAILS" ]; then
                  UNSIGNED_EMAILS="$EMAIL"
                else
                  UNSIGNED_EMAILS="$UNSIGNED_EMAILS,$EMAIL"
                fi
                ALL_SIGNED=false
                if [ "$RESPONSE" = "TIMEOUT" ]; then
                  echo "   ⚠️ $EMAIL - CLA check timeout (assumed NOT signed)"
                else
                  echo "   ❌ $EMAIL - CLA NOT signed (response: $RESPONSE)"
                fi
              else
                if [ -z "$SIGNED_EMAILS" ]; then
                  SIGNED_EMAILS="$EMAIL"
                else
                  SIGNED_EMAILS="$SIGNED_EMAILS,$EMAIL"
                fi
                echo "   ✅ $EMAIL - CLA signed"
              fi

              if [ -z "$CHECKED_EMAILS" ]; then
                CHECKED_EMAILS="$EMAIL"
              else
                CHECKED_EMAILS="$CHECKED_EMAILS,$EMAIL"
              fi
            fi
          done <<< "$VALID_EMAILS"

          echo "emails=$CHECKED_EMAILS" >> $GITHUB_OUTPUT
