def cat_commit(sha):
    import re
    raw = subprocess.run(["git", "cat-file", "commit", sha],
                         capture_output=True, encoding="utf-8", errors="replace",
                         check=True).stdout
    headers, _, msg = raw.partition("\n\n")
    meta = {"parents": [], "author": None, "committer": None}
    pat = re.compile(r"^(.*) <(.*)> (\d+ [+-]\d{4})$")
    for line in headers.split("\n"):
        if line.startswith("tree "):
            meta["tree"] = line.split()[1]
        elif line.startswith("parent "):
            meta["parents"].append(line.split()[1])
        elif line.startswith("author ") or line.startswith("committer "):
            m = pat.match(line.split(" ", 1)[1])
            name, email, when = m.group(1), m.group(2), m.group(3)
            entry = {"name": name, "email": email, "date": to_iso(when)}
            if line.startswith("author "):
                meta["author"] = entry
            else:
                meta["committer"] = entry
    return meta, msg

